// Inicializar estado global del test run
$execution.customData.set('startTime', new Date().toISOString());
$execution.customData.set('totalTests', testCases.length);
$execution.customData.set('testResults', '[]');

return testCases.map(tc => ({ json: tc }));

// Pre-process: preparar el test case actual
const testCase = $input.first().json;

console.log(`\n========================================`);
console.log(`🧪 Ejecutando: ${testCase.id} - ${testCase.name}`);
console.log(`   Categoria: ${testCase.category}`);
console.log(`   Prioridad: ${testCase.priority}`);
console.log(`========================================`);

return [{ json: testCase }];

// Extraer solo el input del test case para pasarlo al sub-workflow
const testCase = $('Pre-Test Log').first().json;
const whatsappInput = testCase.input[0];

// Retornar el objeto WhatsApp directamente
return [{ json: whatsappInput }];

// Evaluar resultado del test
const testCase = $('Pre-Test Log').first().json;
const workflowResult = $input.first().json;

// Extraer el output del workflow
let output = '';
try {
  if (workflowResult.output) {
    output = workflowResult.output;
  } else if (workflowResult.text) {
    output = workflowResult.text;
  } else if (typeof workflowResult === 'string') {
    output = workflowResult;
  } else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) {
  output = '';
}

// Evaluar la métrica
let passed = false;
let error = null;

try {
  const rule = testCase.metrics.rule;
  passed = eval(rule);
} catch (e) {
  error = e.message;
  passed = false;
}

const result = {
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: passed,
  output: output ? output.substring(0, 500) : '(empty)',
  expectedRule: testCase.metrics.rule,
  ruleDescription: testCase.metrics.description,
  error: error,
  executedAt: new Date().toISOString()
};

// Guardar resultado en customData para agregarlo al final
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

console.log(`${passed ? '✅ PASSED' : '❌ FAILED'}: ${testCase.id} - ${testCase.name}`);

return [{ json: result }];

// 1. DATA EXTRACTION
// ------------------------------------------------
let results = [];
let source = 'None';

// Check if input exists and has the 'results' key (matches your specific input)
if (items && items.length > 0 && items[0].json && Array.isArray(items[0].json.results)) {
  results = items[0].json.results;
  source = 'items[0].json.results';
} 
// Fallback: If the input is the array itself
else if (items && items.length > 0 && Array.isArray(items[0].json)) {
  results = items[0].json;
  source = 'items[0].json (Direct)';
}

// Debug Log for the Console Tab
console.log(`\n🔍 DATA SOURCE: ${source}`);
console.log(`📊 RECORDS FOUND: ${results.length}`);

// 2. STATISTICS CALCULATION
// ------------------------------------------------
const total = results.length;
const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);

// Calculate Pass Rate (Avoid division by zero)
const passRateRaw = total > 0 ? (passed.length / total) * 100 : 0;
const passRate = passRateRaw % 1 === 0 ? passRateRaw.toFixed(0) : passRateRaw.toFixed(1);

// Group by Category
const byCategory = results.reduce((acc, curr) => {
  const cat = curr.category || 'UNCATEGORIZED';
  if (!acc[cat]) acc[cat] = { total: 0, passed: 0, failed: 0 };

  acc[cat].total++;
  curr.passed ? acc[cat].passed++ : acc[cat].failed++;
  return acc;
}, {});

// Group by Priority
const byPriority = results.reduce((acc, curr) => {
  const prio = curr.priority || 'UNKNOWN';
  if (!acc[prio]) acc[prio] = { total: 0, passed: 0, failed: 0 };

  acc[prio].total++;
  curr.passed ? acc[prio].passed++ : acc[prio].failed++;
  return acc;
}, {});

// 3. GENERATE MARKDOWN REPORT (For Slack/Telegram/Email)
// ------------------------------------------------
let statusEmoji = failed.length === 0 ? '✅' : '❌';
if (total === 0) statusEmoji = '⚠️';

let mdReport = `*📊 Test Report - GymRatFlow*\n`;
mdReport += `──────────────────────\n`;
mdReport += `*Status:* ${statusEmoji} ${failed.length === 0 ? 'PASS' : 'FAIL'}\n`;
mdReport += `*Score:* ${passRate}% (${passed.length}/${total})\n`;
mdReport += `*Time:* ${new Date().toLocaleString('es-CO')}\n\n`; // Adjusted to your locale context

// Add Category Summary
mdReport += `*📂 Categorías:*\n`;
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const icon = c.failed === 0 ? '✔' : '❗';
  mdReport += `${icon} ${cat}: ${c.passed}/${c.total}\n`;
});

// Add Detailed Failures if any
if (failed.length > 0) {
  mdReport += `\n*🚨 Fallos Detectados:*\n`;
  failed.forEach(f => {
    mdReport += `• *[${f.priority}] ${f.testName}*\n`;
    mdReport += `  _Exp:_ ${f.ruleDescription}\n`;
    // Clean output for message (truncate)
    const cleanOutput = (f.output || 'null').replace(/\n/g, ' ').substring(0, 80);
    mdReport += `  _Got:_ ${cleanOutput}...\n`;
  });
}

// 4. CONSOLE LOGGING (Visual Table for n8n UI)
// ------------------------------------------------
console.log('\n╔══════════════════════════════════════════════╗');
console.log(`║ STATUS: ${statusEmoji}  RATE: ${passRate}% (${passed.length}/${total})`.padEnd(47) + '║');
console.log('╠══════════════════════════════════════════════╣');
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const bar = c.failed === 0 ? 'OK' : 'FAIL';
  console.log(`║ ${cat.padEnd(20)}: ${c.passed}/${c.total} ${bar.padStart(13)} ║`);
});
console.log('╚══════════════════════════════════════════════╝');

// 5. RETURN OUTPUT
// ------------------------------------------------
return [{
  json: {
    meta: {
      timestamp: new Date().toISOString(),
      totalTests: total,
      success: failed.length === 0
    },
    // This is the string you map to your Slack/Email node
    markdownReport: mdReport,
    // This object helps if you need to do conditional logic in Switch nodes next
    stats: {
      passed: passed.length,
      failed: failed.length,
      rate: parseFloat(passRate),
      byCategory,
      byPriority
    },
    // Only return detailed failure info to keep payload light
    failures: failed.map(r => ({
      testId: r.testId,
      name: r.testName,
      category: r.category,
      reason: r.ruleDescription,
      output: r.output
    }))
  }
}];
